package ru.kupiora.radar;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;
public class SyncJob extends JobService {
 static final String CHANNEL="official_changes";
 static void schedule(Context c){JobScheduler scheduler=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);JobInfo existing=scheduler.getPendingJob(101);if(existing!=null&&existing.getIntervalMillis()==24*60*60*1000L)return;scheduler.schedule(new JobInfo.Builder(101,new ComponentName(c,SyncJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(24*60*60*1000L).setPersisted(true).build());}
 public boolean onStartJob(JobParameters p){sync(this,()->jobFinished(p,false));return true;}
 public boolean onStopJob(JobParameters p){return true;}
 static final java.util.List<Runnable> callbacks=new ArrayList<>();static boolean running;
 static synchronized void sync(Context supplied,Runnable done){callbacks.add(done);if(running)return;running=true;final Context c=supplied.getApplicationContext();new Thread(()->{Store.prefs(c).edit().putLong("last_attempt",System.currentTimeMillis()).apply();try{
 // Set only after a reviewed normative feed is deployed. Do not reuse the general news feed.
 Catalog.init(c);String endpoint=Store.prefs(c).getString("feed_endpoint","https://kupiora.ru/radar/legal-feed.json");if(endpoint.isEmpty())throw new Exception("Поток официальных изменений ещё не подключён");
 java.net.URL url=new java.net.URL(endpoint+(endpoint.contains("?")?"&":"?")+"checkedAt="+System.currentTimeMillis());if(!url.getProtocol().equals("https"))throw new Exception("Требуется HTTPS");
 java.net.HttpURLConnection conn=(java.net.HttpURLConnection)url.openConnection();conn.setUseCaches(false);conn.setConnectTimeout(15000);conn.setReadTimeout(15000);String json;try{if(conn.getResponseCode()!=200)throw new Exception("Сервер временно недоступен");try(java.io.InputStream in=conn.getInputStream()){java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream();byte[] chunk=new byte[8192];int len;while((len=in.read(chunk))!=-1){buffer.write(chunk,0,len);if(buffer.size()>2_000_000)throw new Exception("Слишком большой ответ");}byte[] data=buffer.toByteArray();if(data.length>2_000_000)throw new Exception("Слишком большой ответ");json=new String(data,java.nio.charset.StandardCharsets.UTF_8);}}finally{conn.disconnect();}
 java.util.List<JSONObject> items=Feed.parse(json);JSONObject envelope=new JSONObject(json);synchronized(SyncJob.class){Set<String>seen=new HashSet<>(Store.prefs(c).getStringSet("seen",new HashSet<>()));boolean baseline=Store.prefs(c).getBoolean("has_baseline",false);
 Set<String> pending=new HashSet<>(Store.prefs(c).getStringSet("digest_pending",new HashSet<>()));
 JSONObject queued=new JSONObject(Store.prefs(c).getString("digest_documents","{}"));for(JSONObject x:items){String id=x.getString("id");if(DigestPolicy.shouldQueue(x,baseline,seen,Store.selected(c))){pending.add(id);queued.put(id,x);}seen.add(id);}
 Store.prefs(c).edit().putString("feed",json).putString("digest_documents",queued.toString()).putLong("last_success",System.currentTimeMillis()).putStringSet("seen",seen).putStringSet("digest_pending",pending).putBoolean("has_baseline",true).putString("sync_status","Последняя загрузка: "+java.time.LocalDateTime.now().withSecond(0).withNano(0)).apply();
 deliverDigest(c,items);}
 }catch(Exception e){Store.prefs(c).edit().putString("sync_status",e.getMessage()==null?"Обновление недоступно":e.getMessage()).apply();}finally{try{deliverDigest(c,Feed.parse(Store.feed(c)));}catch(Exception ignored){}java.util.List<Runnable> completed;synchronized(SyncJob.class){completed=new ArrayList<>(callbacks);callbacks.clear();running=false;}for(Runnable callback:completed)try{callback.run();}catch(Exception ignored){}}}).start();}
 static synchronized void deliverDigest(Context c,java.util.List<JSONObject> items)throws Exception {
 android.content.SharedPreferences prefs=Store.prefs(c);long now=System.currentTimeMillis(),previous=prefs.getLong("digest_last",0);if(previous==0){prefs.edit().putLong("digest_last",now).apply();return;}
 String interval=prefs.getString("digest_interval","daily");if(!DigestPolicy.isDue(previous,now,interval,java.time.ZoneId.systemDefault()))return;
 Set<String> pending=new HashSet<>(prefs.getStringSet("digest_pending",new HashSet<>()));JSONObject queued=new JSONObject(prefs.getString("digest_documents","{}"));for(JSONObject x:items)if(pending.contains(x.getString("id")))queued.put(x.getString("id"),x);
 java.util.List<JSONObject> eligible=new ArrayList<>();Set<String> remaining=new HashSet<>(pending);for(String id:pending){JSONObject x=queued.optJSONObject(id);if(x==null)continue;if(!Store.matches(c,x)||x.optBoolean("archive")){remaining.remove(id);queued.remove(id);continue;}eligible.add(x);}
 eligible.sort((a,b)->a.optString("publishedAt").compareTo(b.optString("publishedAt")));
 int added=0;StringBuilder summary=new StringBuilder();for(JSONObject x:eligible){if(Inbox.addDocument(c,x)){added++;if(added<=3)summary.append("• ").append(x.optString("title")).append("\n");}remaining.remove(x.getString("id"));queued.remove(x.getString("id"));}
 prefs.edit().putStringSet("digest_pending",remaining).putString("digest_documents",queued.toString()).putLong("digest_last",now).apply();
 if(added>0)notify(c,101,"Радар жизни · новых изменений: "+added,summary.toString().trim());
 }

 static void channel(Context c){NotificationChannel channel=new NotificationChannel(CHANNEL,"Официальные изменения",NotificationManager.IMPORTANCE_DEFAULT);channel.setShowBadge(true);c.getSystemService(NotificationManager.class).createNotificationChannel(channel);}
 static void notify(Context c,int id,String title,String summary){notify(c,id,title,summary,false);}
 static void notify(Context c,int id,String title,String summary,boolean silent){channel(c);NotificationManager nm=c.getSystemService(NotificationManager.class);if(!nm.areNotificationsEnabled())return;nm.cancel(999);PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).putExtra("open_notifications",true),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);try{nm.notify(101,new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(summary).setStyle(new Notification.BigTextStyle().bigText(summary)).setNumber(Inbox.count(c)).setBadgeIconType(Notification.BADGE_ICON_SMALL).setContentIntent(pi).setOnlyAlertOnce(true).setGroup("radar-updates").setGroupAlertBehavior(silent?Notification.GROUP_ALERT_SUMMARY:Notification.GROUP_ALERT_ALL).setAutoCancel(true).build());}catch(SecurityException ignored){}}
 static void updateSystemBadge(Context c){NotificationManager nm=c.getSystemService(NotificationManager.class);int count=Inbox.count(c);if(count==0){nm.cancelAll();return;}JSONArray entries=Inbox.load(c);for(int i=0;i<entries.length();i++){JSONObject x=entries.optJSONObject(i);if(x!=null&&!x.optBoolean("read")){notify(c,101,x.optString("title"),x.optString("body"),true);break;}}}
 static void testNotification(Context c){try{Inbox.add(c,"test:"+System.currentTimeMillis(),"Тест · Радар жизни","Проверка колокольчика и значка приложения. Это не изменение закона.",true);notify(c,101,"Тест · Радар жизни","Проверка уведомлений — не изменение закона.");if(!c.getSystemService(NotificationManager.class).areNotificationsEnabled())android.widget.Toast.makeText(c,"Пример добавлен в колокольчик. Для значка приложения разрешите системные уведомления.",android.widget.Toast.LENGTH_LONG).show();}catch(Exception ignored){}}
}
